PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY,name TEXT NOT NULL,email TEXT NOT NULL UNIQUE,password_hash TEXT NOT NULL,role TEXT NOT NULL CHECK(role IN('student','organizer','admin')),created_at TEXT DEFAULT(datetime('now')));
CREATE TABLE IF NOT EXISTS events(id INTEGER PRIMARY KEY,organizer_id INTEGER NOT NULL REFERENCES users(id),title TEXT NOT NULL,description TEXT,category TEXT NOT NULL,banner TEXT,venue TEXT NOT NULL,event_date TEXT NOT NULL,start_time TEXT,end_time TEXT,reg_open TEXT NOT NULL,reg_close TEXT NOT NULL,capacity INTEGER NOT NULL CHECK(capacity>0),eligibility TEXT,contact TEXT,form_type TEXT NOT NULL DEFAULT'',form_fields TEXT NOT NULL DEFAULT'[]',status TEXT NOT NULL DEFAULT'pending' CHECK(status IN('pending','published','rejected','changes_requested')),created_at TEXT DEFAULT(datetime('now')),updated_at TEXT DEFAULT(datetime('now')));
CREATE TABLE IF NOT EXISTS event_approval_history(id INTEGER PRIMARY KEY,event_id INTEGER NOT NULL REFERENCES events(id),actor_id INTEGER NOT NULL REFERENCES users(id),action TEXT NOT NULL,reason TEXT,created_at TEXT DEFAULT(datetime('now')));
CREATE TABLE IF NOT EXISTS registrations(id INTEGER PRIMARY KEY,reg_code TEXT NOT NULL UNIQUE,event_id INTEGER NOT NULL REFERENCES events(id),student_id INTEGER NOT NULL REFERENCES users(id),status TEXT NOT NULL DEFAULT'confirmed' CHECK(status IN('confirmed','cancelled')),qr_token TEXT,answers TEXT NOT NULL DEFAULT'[]',created_at TEXT DEFAULT(datetime('now')),UNIQUE(event_id,student_id));
CREATE INDEX IF NOT EXISTS idx_ev_status ON events(status,event_date);
CREATE INDEX IF NOT EXISTS idx_reg_event ON registrations(event_id,status);
CREATE TABLE IF NOT EXISTS attendance_records(id INTEGER PRIMARY KEY,registration_id INTEGER NOT NULL UNIQUE REFERENCES registrations(id),event_id INTEGER NOT NULL REFERENCES events(id),checked_in_by INTEGER NOT NULL REFERENCES users(id),checked_in_at TEXT DEFAULT(datetime('now')));
CREATE TABLE IF NOT EXISTS certificates(id INTEGER PRIMARY KEY,cert_id TEXT NOT NULL UNIQUE,registration_id INTEGER NOT NULL UNIQUE REFERENCES registrations(id),file_path TEXT NOT NULL,issued_at TEXT DEFAULT(datetime('now')),email_status TEXT NOT NULL DEFAULT'pending',email_error TEXT,signed INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS notifications(id INTEGER PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users(id),message TEXT NOT NULL,is_read INTEGER NOT NULL DEFAULT 0,created_at TEXT DEFAULT(datetime('now')));
CREATE INDEX IF NOT EXISTS idx_notif_user ON notifications(user_id,is_read);
CREATE TABLE IF NOT EXISTS organizer_requests(id INTEGER PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users(id),organization TEXT,event_title TEXT NOT NULL,event_category TEXT,event_description TEXT,expected_date TEXT,reason TEXT,status TEXT NOT NULL DEFAULT'pending' CHECK(status IN('pending','approved','rejected','revoked')),admin_note TEXT,reviewed_by INTEGER REFERENCES users(id),reviewed_at TEXT,created_at TEXT DEFAULT(datetime('now')));
CREATE INDEX IF NOT EXISTS idx_orgreq_status ON organizer_requests(status,user_id);
CREATE TABLE IF NOT EXISTS certificate_settings(id INTEGER PRIMARY KEY CHECK(id=1),authority_name TEXT NOT NULL,designation TEXT NOT NULL,signature_b64 TEXT,updated_by INTEGER REFERENCES users(id),updated_at TEXT DEFAULT(datetime('now')));
